import{_ as a,o as i,c as n,ao as r}from"./chunks/framework.DlOpO9-F.js";const u=JSON.parse('{"title":"Child Safety Standards","description":"","frontmatter":{},"headers":[],"relativePath":"child-safety.md","filePath":"child-safety.md"}'),o={name:"child-safety.md"};function t(s,e,d,l,h,p){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="child-safety-standards" tabindex="-1">Child Safety Standards <a class="header-anchor" href="#child-safety-standards" aria-label="Permalink to “Child Safety Standards”">​</a></h1><p>Effective date: 2026-10-13</p><p>These standards cover the Open Grind app, published on Google Play by Viktor Shchelochkov and made by Open Grind Governance. They apply to everyone who uses Open Grind and to its community spaces: git.opengrind.org and the Open Grind Matrix rooms.</p><h2 id="child-sexual-abuse-and-exploitation-is-prohibited" tabindex="-1">Child sexual abuse and exploitation is prohibited <a class="header-anchor" href="#child-sexual-abuse-and-exploitation-is-prohibited" aria-label="Permalink to “Child sexual abuse and exploitation is prohibited”">​</a></h2><p>Open Grind prohibits child sexual abuse and exploitation (CSAE). This includes:</p><ul><li>child sexual abuse material (CSAM), including drawn, edited or AI-generated images, and asking for it or linking to it</li><li>sexualizing minors in words, images or video</li><li>grooming: building a minor&#39;s trust in order to sexually abuse them</li><li>sextortion: threatening a minor to get sexual images, money or a meeting</li><li>trafficking of children</li><li>arranging to meet a minor for sex</li></ul><h2 id="adults-only" tabindex="-1">Adults only <a class="header-anchor" href="#adults-only" aria-label="Permalink to “Adults only”">​</a></h2><p>Open Grind is only for adults 18 and older. Minors must not use Open Grind.</p><h2 id="report-abuse" tabindex="-1">Report abuse <a class="header-anchor" href="#report-abuse" aria-label="Permalink to “Report abuse”">​</a></h2><ul><li>Report a profile or message to Grindr with Report in Open Grind, and choose Underage for anything involving a minor.</li><li>Report anything on git.opengrind.org or in the Open Grind Matrix rooms to <a href="mailto:admin@opengrind.org" target="_blank" rel="noreferrer">admin@opengrind.org</a>. Never send images of abuse to anyone, including us. Describe where you saw them instead.</li></ul><h2 id="profiles-photos-and-messages" tabindex="-1">Profiles, photos and messages <a class="header-anchor" href="#profiles-photos-and-messages" aria-label="Permalink to “Profiles, photos and messages”">​</a></h2><p>Grindr hosts and moderates all profiles, photos and messages in Open Grind. <a href="https://www.grindr.com/community-guidelines" target="_blank" rel="noreferrer">Grindr&#39;s Community Guidelines</a> apply to them as well as these standards.</p>',12)])])}const c=a(o,[["render",t]]);export{u as __pageData,c as default};
